def resolve(block, sheet):
    """Старое имя листа (из данных блока) → имя листа в файле отчёта."""
    return LINKS.get(block, {}).get(sheet, sheet)


def present(block, selected):
    """Листы файла блока в порядке отчёта; при файле 06 переехавшие листы — только в 06."""
    out = list(ORDERS.get(block, []))
    if 'SEO' in (selected or ()) and block != 'SEO':
        moved = {'Ошибки': ('Поисковые ошибки',), 'Нагрузка и безопасность': ('Паразитные адреса',), 'Боты': ('ИИ-роботы',), 'Маркетинг': ('Органика',)}.get(block, ())
        out = [s for s in out if s not in moved]
    return out
